{"command":"cd /workspace && rmdir src && cat > log.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

// Log levels
const (
	levelDebug = iota
	levelInfo
	levelWarn
	levelError
)

var (
	logMinLevel = levelInfo
	logColor    = false
)

var levelNames = map[int]string{
	levelDebug: "DEBUG",
	levelInfo:  "INFO",
	levelWarn:  "WARN",
	levelError: "ERROR",
}

var levelColors = map[int]string{
	levelDebug: "36;1",
	levelInfo:  "32;1",
	levelWarn:  "33;1",
	levelError: "31;1",
}

func initLogging() {
	logColor = isTerminal(os.Stderr.Fd())
}

func setDebugLogging(enabled bool) {
	if enabled {
		logMinLevel = levelDebug
	} else {
		logMinLevel = levelInfo
	}
}

func logAt(level int, msg string) {
	if level < logMinLevel {
		return
	}
	name := levelNames[level]
	ts := time.Now().Format("2006-01-02 15:04:05")
	// pad "[LEVEL]" to 7 chars then a space
	pad := strings.Repeat(" ", 7-len(name)-2)
	var label string
	if logColor {
		label = fmt.Sprintf("[\x1b[%sm%s\x1b[0m]", levelColors[level], name)
	} else {
		label = "[" + name + "]"
	}
	fmt.Fprintf(os.Stderr, "%s %s %s%s\n", ts, label, pad, msg)
}

func logDebug(msg string)                        { logAt(levelDebug, msg) }
func logDebugf(format string, a ...interface{})  { logAt(levelDebug, fmt.Sprintf(format, a...)) }
func logInfo(msg string)                         { logAt(levelInfo, msg) }
func logInfof(format string, a ...interface{})   { logAt(levelInfo, fmt.Sprintf(format, a...)) }
func logWarn(msg string)                         { logAt(levelWarn, msg) }
func logWarnf(format string, a ...interface{})   { logAt(levelWarn, fmt.Sprintf(format, a...)) }
func logError(msg string)                        { logAt(levelError, msg) }
func logErrorf(format string, a ...interface{})  { logAt(levelError, fmt.Sprintf(format, a...)) }
EOF
cat > term.go <<'EOF'
package main

import (
	"syscall"
	"unsafe"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   uint8
	Cc     [19]uint8
	Ispeed uint32
	Ospeed uint32
}

const (
	ioctlTCGETS = 0x5401
	ioctlTCSETS = 0x5402
	flagECHO    = 0x8
)

func ioctlTermios(fd uintptr, req uintptr, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}

func isTerminal(fd uintptr) bool {
	var t termios
	return ioctlTermios(fd, ioctlTCGETS, &t) == nil
}

// readPassword reads a line from fd with echo disabled. Returns the line
// without trailing newline.
func readPassword(fd uintptr) (string, error) {
	var old termios
	if err := ioctlTermios(fd, ioctlTCGETS, &old); err != nil {
		return "", err
	}
	newState := old
	newState.Lflag &^= flagECHO
	if err := ioctlTermios(fd, ioctlTCSETS, &newState); err != nil {
		return "", err
	}
	defer ioctlTermios(fd, ioctlTCSETS, &old)

	var buf []byte
	var b [1]byte
	for {
		n, err := syscall.Read(int(fd), b[:])
		if n == 1 {
			if b[0] == '\n' {
				break
			}
			if b[0] == '\r' {
				continue
			}
			buf = append(buf, b[0])
		}
		if err != nil || n == 0 {
			if len(buf) == 0 && err == nil {
				return "", errEOF
			}
			if err != nil {
				return string(buf), err
			}
			break
		}
	}
	return string(buf), nil
}
EOF
echo ok"}

