{"command":"cd /workspace && cat > option.go <<'EOF'
package main

import (
	"fmt"
	"sort"
	"strings"
)

type OptionType int

const (
	OptionTypeString OptionType = iota
	OptionTypeBool
)

// Option represents a command-line / option-file option.
type Option struct {
	Name          string
	Shorthand     rune
	Type          OptionType
	Default       string
	Description   string
	RequireValue  bool
	HiddenOnCLI   bool
	Group         string
	AllowedValues []string
}

func StringOption(name string, shorthand rune, defaultValue, description string) *Option {
	return &Option{
		Name:         name,
		Shorthand:    shorthand,
		Type:         OptionTypeString,
		Default:      defaultValue,
		Description:  description,
		RequireValue: true,
	}
}

func BoolOption(name string, shorthand rune, defaultValue bool, description string) *Option {
	def := ""
	if defaultValue {
		def = "1"
	}
	return &Option{
		Name:         name,
		Shorthand:    shorthand,
		Type:         OptionTypeBool,
		Default:      def,
		Description:  description,
		RequireValue: false,
	}
}

func (opt *Option) Hidden() *Option {
	opt.HiddenOnCLI = true
	return opt
}

func (opt *Option) ValueOptional() *Option {
	opt.RequireValue = false
	return opt
}

func (opt *Option) ValueRequired() *Option {
	opt.RequireValue = true
	return opt
}

func (opt *Option) InGroup(g string) *Option {
	opt.Group = g
	return opt
}

func (opt *Option) Allowed(values ...string) *Option {
	opt.AllowedValues = values
	return opt
}

func (opt *Option) HasShorthand() bool {
	return opt.Shorthand != 0
}

func (opt *Option) defaultIsTrue() bool {
	return opt.Type == OptionTypeBool && boolValue(opt.Default)
}

// usageString returns the left-hand side of the help line for this option
func (opt *Option) usageString() string {
	var sb strings.Builder
	if opt.HasShorthand() {
		sb.WriteString(fmt.Sprintf("  -%c, ", opt.Shorthand))
	} else {
		sb.WriteString("      ")
	}
	if opt.Type == OptionTypeBool && opt.defaultIsTrue() {
		sb.WriteString("--[skip-]" + opt.Name)
	} else {
		sb.WriteString("--" + opt.Name)
		if opt.Type == OptionTypeString {
			if opt.RequireValue {
				sb.WriteString(" value")
			} else {
				sb.WriteString("[=value]")
			}
		}
	}
	return sb.String()
}

func (opt *Option) descriptionString() string {
	desc := opt.Description
	if len(opt.AllowedValues) > 0 {
		quoted := make([]string, len(opt.AllowedValues))
		for n, v := range opt.AllowedValues {
			quoted[n] = fmt.Sprintf("%q", v)
		}
		desc += fmt.Sprintf(" (valid values: %s)", strings.Join(quoted, ", "))
	}
	if opt.Type == OptionTypeBool {
		if opt.defaultIsTrue() {
			desc += fmt.Sprintf(" (enabled by default; disable with --skip-%s)", opt.Name)
		}
	} else if opt.Default != "" {
		desc += fmt.Sprintf(" (default %q)", opt.Default)
	}
	return desc
}

func boolValue(s string) bool {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "", "0", "off", "false":
		return false
	}
	return true
}

// OptionGroup is a named group of options for help output
type OptionGroup struct {
	Name    string
	Options []*Option
}

func sortOptionsByName(opts []*Option) {
	sort.Slice(opts, func(i, j int) bool { return opts[i].Name < opts[j].Name })
}
EOF
echo ok"}

