package main

import (
	"fmt"
	"strconv"
	"strings"
)

// OptionValuer is a source of option values
type OptionValuer interface {
	OptionValue(optionName string) (value string, ok bool)
	OptionSuppliedWithoutValue(optionName string) bool
}

// SimpleSource is a basic map-backed option source
type SimpleSource struct {
	values  map[string]string
	noValue map[string]bool
}

func NewSimpleSource() *SimpleSource {
	return &SimpleSource{values: make(map[string]string), noValue: make(map[string]bool)}
}

func (s *SimpleSource) OptionValue(name string) (string, bool) {
	v, ok := s.values[name]
	return v, ok
}

func (s *SimpleSource) OptionSuppliedWithoutValue(name string) bool {
	return s.noValue[name]
}

func (s *SimpleSource) Set(name, value string) {
	s.values[name] = value
	delete(s.noValue, name)
}

// CommandLine holds parsed CLI state
type CommandLine struct {
	Command      *Command
	OptionValues map[string]string
	noValue      map[string]bool
	ArgValues    []string
}

func (cli *CommandLine) OptionValue(name string) (string, bool) {
	v, ok := cli.OptionValues[name]
	return v, ok
}

func (cli *CommandLine) OptionSuppliedWithoutValue(name string) bool {
	return cli.noValue[name]
}

// Config combines CLI and other sources
type Config struct {
	CLI      *CommandLine
	sources  []OptionValuer // later entries have higher priority
	runtimeO map[string]string
}

func NewConfig(cli *CommandLine, sources ...OptionValuer) *Config {
	return &Config{CLI: cli, sources: sources, runtimeO: make(map[string]string)}
}

func (cfg *Config) Clone() *Config {
	c := &Config{
		CLI:      cfg.CLI,
		sources:  make([]OptionValuer, len(cfg.sources)),
		runtimeO: make(map[string]string),
	}
	copy(c.sources, cfg.sources)
	for k, v := range cfg.runtimeO {
		c.runtimeO[k] = v
	}
	return c
}

func (cfg *Config) AddSource(src OptionValuer) {
	cfg.sources = append(cfg.sources, src)
}

// SetRuntimeOverride sets a value that takes precedence over all other sources
func (cfg *Config) SetRuntimeOverride(name, value string) {
	cfg.runtimeO[name] = value
}

func (cfg *Config) FindOption(name string) *Option {
	opt, _ := cfg.CLI.Command.OptionByName(name)
	return opt
}

// highestSource returns the highest-priority source supplying name
func (cfg *Config) highestSource(name string) (OptionValuer, string, bool) {
	if v, ok := cfg.CLI.OptionValue(name); ok {
		return cfg.CLI, v, true
	}
	for i := len(cfg.sources) - 1; i >= 0; i-- {
		if v, ok := cfg.sources[i].OptionValue(name); ok {
			return cfg.sources[i], v, true
		}
	}
	return nil, "", false
}

func (cfg *Config) Get(name string) string {
	if v, ok := cfg.runtimeO[name]; ok {
		return v
	}
	if _, v, ok := cfg.highestSource(name); ok {
		return v
	}
	if opt := cfg.FindOption(name); opt != nil {
		return opt.Default
	}
	return ""
}

func (cfg *Config) GetRaw(name string) string {
	return cfg.Get(name)
}

func (cfg *Config) GetBool(name string) bool {
	return boolValue(cfg.Get(name))
}

func (cfg *Config) GetInt(name string) (int, error) {
	s := strings.TrimSpace(cfg.Get(name))
	if s == "" {
		return 0, nil
	}
	return strconv.Atoi(s)
}

func (cfg *Config) GetIntOrDefault(name string) int {
	n, err := cfg.GetInt(name)
	if err != nil {
		if opt := cfg.FindOption(name); opt != nil {
			n, _ = strconv.Atoi(opt.Default)
		}
	}
	return n
}

// GetBytes parses a size value with optional K/M/G suffix
func (cfg *Config) GetBytes(name string) (uint64, error) {
	s := strings.TrimSpace(strings.ToLower(cfg.Get(name)))
	if s == "" {
		return 0, nil
	}
	mult := uint64(1)
	switch s[len(s)-1] {
	case 'k':
		mult = 1024
		s = s[:len(s)-1]
	case 'm':
		mult = 1024 * 1024
		s = s[:len(s)-1]
	case 'g':
		mult = 1024 * 1024 * 1024
		s = s[:len(s)-1]
	}
	n, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, err
	}
	return n * mult, nil
}

func (cfg *Config) GetEnum(name string, allowed ...string) (string, error) {
	value := strings.ToLower(cfg.Get(name))
	for _, a := range allowed {
		if value == strings.ToLower(a) {
			return a, nil
		}
	}
	quoted := make([]string, len(allowed))
	for n, a := range allowed {
		quoted[n] = fmt.Sprintf("%q", a)
	}
	return "", fmt.Errorf("Option %s can only be set to one of these values: %s", name, strings.Join(quoted, ", "))
}

// GetSlice splits a value on a delimiter, trimming whitespace and dropping blanks
func (cfg *Config) GetSlice(name string, delimiter rune, unwrapFull bool) []string {
	return splitSlice(cfg.Get(name), delimiter, unwrapFull)
}

func splitSlice(value string, delimiter rune, unwrapFull bool) []string {
	value = strings.TrimSpace(value)
	if unwrapFull && len(value) >= 2 {
		if (value[0] == '"' && value[len(value)-1] == '"') || (value[0] == '\'' && value[len(value)-1] == '\'') {
			value = value[1 : len(value)-1]
		}
	}
	parts := strings.Split(value, string(delimiter))
	result := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			result = append(result, p)
		}
	}
	return result
}

func (cfg *Config) Supplied(name string) bool {
	_, _, ok := cfg.highestSource(name)
	return ok
}

func (cfg *Config) SuppliedWithValue(name string) bool {
	src, _, ok := cfg.highestSource(name)
	if !ok {
		return false
	}
	return !src.OptionSuppliedWithoutValue(name)
}

func (cfg *Config) OnCLI(name string) bool {
	_, ok := cfg.CLI.OptionValue(name)
	return ok
}

func (cfg *Config) Changed(name string) bool {
	opt := cfg.FindOption(name)
	if opt == nil {
		return cfg.Supplied(name)
	}
	if opt.Type == OptionTypeBool {
		return cfg.GetBool(name) != boolValue(opt.Default)
	}
	return cfg.Get(name) != opt.Default
}
EOF
echo ok"}

