package main

import (
	"errors"
	"fmt"
	"os"
	"strings"
)

const (
	CodeSuccess          = 0
	CodeDifferencesFound = 1
	CodePartialError     = 1
	CodeFatalError       = 2
	CodeBadUsage         = 64
	CodeBadInput         = 65
	CodeNoInput          = 66
	CodeCantCreate       = 73
	CodeBadConfig        = 78
)

var errEOF = errors.New("EOF")

// ExitValue is an error carrying an exit code
type ExitValue struct {
	Code    int
	message string
}

func NewExitValue(code int, format string, a ...interface{}) *ExitValue {
	return &ExitValue{Code: code, message: fmt.Sprintf(format, a...)}
}

func WrapExitCode(code int, err error) *ExitValue {
	if err == nil {
		return nil
	}
	return &ExitValue{Code: code, message: err.Error()}
}

func (ev *ExitValue) Error() string {
	if ev == nil {
		return ""
	}
	return ev.message
}

func ExitCode(err error) int {
	if err == nil {
		return CodeSuccess
	}
	var ev *ExitValue
	if errors.As(err, &ev) {
		return ev.Code
	}
	return CodeFatalError
}

// ConfigError wraps an error indicating a configuration problem (exit 78)
type ConfigError struct {
	err error
}

func NewConfigError(format string, a ...interface{}) ConfigError {
	return ConfigError{err: fmt.Errorf(format, a...)}
}

func (ce ConfigError) Error() string {
	return ce.err.Error()
}

func (ce ConfigError) Unwrap() error {
	return ce.err
}

func IsConfigError(err error) bool {
	var ce ConfigError
	return errors.As(err, &ce)
}

// Exit logs the error (if any) and exits the process with the right code.
func Exit(err error) {
	code := ExitCode(err)
	if err != nil {
		msg := err.Error()
		if msg != "" {
			for _, line := range strings.Split(msg, "\n") {
				logError(line)
			}
		}
	}
	if code == CodeSuccess {
		logDebug("Exit code 0 (SUCCESS)")
	} else {
		logDebugf("Exit code %d", code)
	}
	os.Exit(code)
}
