func unquoteOptionValue(value string) (string, error) {
	if value == "" {
		return value, nil
	}
	first := value[0]
	last := value[len(value)-1]
	startsQuoted := first == '\'' || first == '"'
	endsQuoted := last == '\'' || last == '"'
	if startsQuoted || endsQuoted {
		if !startsQuoted || !endsQuoted || len(value) < 2 || first != last {
			return "", fmt.Errorf("Quoted value has no terminating quote")
		}
		value = value[1 : len(value)-1]
		// process escapes
		var sb strings.Builder
		for i := 0; i < len(value); i++ {
			c := value[i]
			if c == '\\' && i+1 < len(value) {
				i++
				switch value[i] {
				case 'b':
					sb.WriteByte('\b')
				case 't':
					sb.WriteByte('\t')
				case 'n':
					sb.WriteByte('\n')
				case 'r':
					sb.WriteByte('\r')
				case 's':
					sb.WriteByte(' ')
				case '\\':
					sb.WriteByte('\\')
				case '"':
					sb.WriteByte('"')
				case '\'':
					sb.WriteByte('\'')
				default:
					sb.WriteByte('\\')
					sb.WriteByte(value[i])
				}
				continue
			}
			sb.WriteByte(c)
		}
		return sb.String(), nil
	}
	return value, nil
