// Contents renders the file contents
func (f *OptionFile) Contents() string {
	var sb strings.Builder
	first := true
	for _, s := range f.sections {
		if s.Name == "" && len(s.order) == 0 {
			continue
		}
		if !first {
			sb.WriteString("\n")
		}
		first = false
		if s.Name != "" {
			sb.WriteString("[" + s.Name + "]\n")
		}
		names := make([]string, len(s.order))
		copy(names, s.order)
		sort.Strings(names)
		for _, name := range names {
			if s.noValue[name] {
				sb.WriteString(name + "\n")
				continue
			}
			v := s.Values[name]
			if opt, ok := f.knownOptions[name]; ok && opt.Type == OptionTypeBool {
				if boolValue(v) {
					sb.WriteString(name + "\n")
				} else {
					sb.WriteString("skip-" + name + "\n")
				}
				continue
			}
			sb.WriteString(fmt.Sprintf("%s=%s\n", name, v))
		}
	}
	return sb.String()
}

func (f *OptionFile) Write(overwrite bool) error {
	path := f.Path()
	if !overwrite {
		if _, err := os.Stat(path); err == nil {
			return fmt.Errorf("File %s already exists; not overwriting", path)
		}
	}
	return os.WriteFile(path, []byte(f.Contents()), 0666)
}
