package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// allKnownOptions returns the union of options across all commands, used for
// validating option files.
func allKnownOptions(root *Command) map[string]*Option {
	result := make(map[string]*Option)
	var walk func(c *Command)
	walk = func(c *Command) {
		for name, opt := range c.Options {
			if _, exists := result[name]; !exists {
				result[name] = opt
			}
		}
		for _, sub := range c.SubCommands {
			walk(sub)
		}
	}
	walk(root)
	return result
}

var knownOptionsCache map[string]*Option

func knownOptions() map[string]*Option {
	if knownOptionsCache == nil {
		knownOptionsCache = allKnownOptions(rootCommand)
	}
	return knownOptionsCache
}

func homeDir() string {
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	h, _ := os.UserHomeDir()
	return h
}

// AddGlobalConfigFiles reads global option files and adds them as config sources.
func AddGlobalConfigFiles(cfg *Config) error {
	type globalFile struct {
		dir, name string
		myCnf     bool
	}
	files := []globalFile{
		{"/etc", "skeema", false},
		{"/usr/local/etc", "skeema", false},
	}
	home := homeDir()
	if home != "" {
		if cfg.GetBool("my-cnf") {
			files = append(files, globalFile{home, ".my.cnf", true})
		}
		files = append(files, globalFile{home, ".skeema", false})
	}
	if cfg.OnCLI("my-cnf") || cfg.Supplied("my-cnf") && !cfg.GetBool("my-cnf") {
		logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
	}
	for _, gf := range files {
		f := NewOptionFile(gf.dir, gf.name)
		fi, err := os.Stat(f.Path())
		if err != nil || fi.IsDir() {
			continue
		}
		if gf.myCnf {
			f.IgnoreUnknownOptions = true
			f.IgnoredOptions["host"] = true
			f.IgnoredOptions["schema"] = true
			f.IgnoredOptions["socket"] = true
			f.IgnoredOptions["port"] = false
		}
		if err := f.Read(knownOptions()); err != nil {
			logWarnf("Ignoring global option file %s due to parse error: %s", f.Path(), err.Error())
			continue
		}
		if gf.myCnf {
			f.UseSection("mysql", "client", "skeema")
		} else {
			f.UseSection(environmentName(cfg))
		}
		cfg.AddSource(f)
	}
	return nil
}

// environmentName returns the environment positional arg, or "production"
func environmentName(cfg *Config) string {
	if cfg.CLI.Command.Name == "init" || cfg.CLI.Command.Name == "add-environment" {
		if cfg.HasArg("environment") {
			return cfg.Arg("environment")
		}
		return "production"
	}
	if cfg.HasArg("environment") {
		return cfg.Arg("environment")
	}
	return "production"
}

// checkRestrictedOptions enforces that host and schema are only settable in
// .skeema dir option files for most commands.
func checkRestrictedOptions(cfg *Config) error {
	cmdName := cfg.CLI.Command.Name
	if cmdName == "init" {
		return nil
	}
	check := func(name string) error {
		src, _, ok := cfg.highestSource(name)
		if !ok {
			return nil
		}
		var via string
		if src == OptionValuer(cfg.CLI) {
			via = "command line"
		} else if f, ok := src.(*OptionFile); ok {
			via = f.Path()
		} else {
			return nil
		}
		return NewExitValue(CodeBadConfig, "The %s option cannot be set via %s for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options", name, via)
	}
	if cmdName != "add-environment" {
		if err := check("host"); err != nil {
			return err
		}
	}
	return check("schema")
}

const passwordPromptErrorExtra = "Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password"

// processPasswordOption handles interactive password prompting when the
// password option was supplied without a value on the CLI or in a global file.
func processPasswordOption(cfg *Config) error {
	if cfg.Supplied("password") && !cfg.SuppliedWithValue("password") {
		pw, err := promptPassword("Enter password: ")
		if err != nil {
			return NewExitValue(CodeBadConfig, "%s\n%s", err.Error(), passwordPromptErrorExtra)
		}
		cfg.SetRuntimeOverride("password", pw)
	}
	return nil
}

// promptPassword prints a prompt to STDERR and reads a password from STDIN
// without echo. Returns an error if STDIN is not a terminal.
func promptPassword(prompt string) (string, error) {
	fmt.Fprint(os.Stderr, prompt)
	defer fmt.Fprintln(os.Stderr)
	if !isTerminal(os.Stdin.Fd()) {
		return "", fmt.Errorf("STDIN must be a TTY to read password")
	}
	pw, err := readPassword(os.Stdin.Fd())
	if err != nil {
		return "", err
	}
	return pw, nil
}

// resolvedPassword returns the effective password value, expanding $MYSQL_PWD
func resolvedPassword(cfg *Config) string {
	pw := cfg.Get("password")
	if pw == "$MYSQL_PWD" && !cfg.Supplied("password") {
		return os.Getenv("MYSQL_PWD")
	}
	return pw
}

func absPath(p string) string {
	a, err := filepath.Abs(p)
	if err != nil {
		return p
	}
	return a
}

func pluralize(n int, singular, plural string) string {
	if n == 1 {
		return singular
	}
	return plural
}

func countAndNoun(n int, singular, plural string) string {
	return fmt.Sprintf("%d %s", n, pluralize(n, singular, plural))
}

func trimPathSuffix(p string) string {
	return strings.TrimRight(p, "/")
}
EOF
echo ok"}

