package main

import (
	"fmt"
	"os"
	"strings"
	"unicode"
)

type StatementType int

const (
	StatementTypeUnknown StatementType = iota
	StatementTypeNoop
	StatementTypeCommand
	StatementTypeCreate
	StatementTypeCreateUnsupported
)

// Statement is a single SQL statement (or noop/command) parsed from a file
type Statement struct {
	File            string
	LineNo          int
	CharNo          int
	Text            string
	Type            StatementType
	ObjectType      string
	ObjectName      string
	ObjectQualifier string
	Delimiter       string
	Error           error
}

func (stmt *Statement) Location() string {
	if stmt.File == "" && stmt.LineNo == 0 {
		return "unknown:0:0"
	}
	return fmt.Sprintf("%s:%d:%d", stmt.File, stmt.LineNo, stmt.CharNo)
}

func (stmt *Statement) ObjectKey() string {
	return stmt.ObjectType + ":" + stmt.ObjectQualifier + ":" + stmt.ObjectName
}

type parsePos struct {
	line, col int
}

func (p parsePos) String() string {
	if p.col > 1 {
		return fmt.Sprintf("line %d, column %d", p.line, p.col)
	}
	return fmt.Sprintf("line %d", p.line)
}

type sqlParser struct {
	runes     []rune
	pos       int
	line      int
	col       int
	file      string
	delimiter string
	stmts     []*Statement
	err       error
}

func ParseStatementsInFile(filePath string) ([]*Statement, error) {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return nil, err
	}
	return ParseStatementsInString(filePath, string(data))
}

func ParseStatementsInString(filePath, contents string) ([]*Statement, error) {
	p := &sqlParser{
		runes:     []rune(contents),
		line:      1,
		col:       1,
		file:      filePath,
		delimiter: ";",
	}
	// strip UTF-8 BOM
	if len(p.runes) > 0 && p.runes[0] == 0xFEFF {
		p.runes = p.runes[1:]
	}
	for !p.eof() {
		if err := p.nextStatement(); err != nil {
			return p.stmts, err
		}
	}
	return p.stmts, nil
}

func (p *sqlParser) eof() bool {
	return p.pos >= len(p.runes)
}

func (p *sqlParser) peek() rune {
	if p.eof() {
		return 0
	}
	return p.runes[p.pos]
}

func (p *sqlParser) peekAt(n int) rune {
	if p.pos+n >= len(p.runes) {
		return 0
	}
	return p.runes[p.pos+n]
}

func (p *sqlParser) advance() rune {
	r := p.runes[p.pos]
	p.pos++
	if r == '\n' {
		p.line++
		p.col = 1
	} else {
		p.col++
	}
	return r
}

func (p *sqlParser) curPos() parsePos {
	return parsePos{p.line, p.col}
}

func (p *sqlParser) hasPrefix(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.runes) {
		return false
	}
	for i, r := range rs {
		if p.runes[p.pos+i] != r {
			return false
		}
	}
	return true
}

func (p *sqlParser) hasPrefixFold(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.runes) {
		return false
	}
	for i, r := range rs {
		if unicode.ToLower(p.runes[p.pos+i]) != unicode.ToLower(r) {
			return false
		}
	}
	return true
}

func isSpaceRune(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v'
}

func isWordRune(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r) || r >= 0x80
}

// atLineComment returns true if positioned at the start of a -- or # comment
func (p *sqlParser) atLineComment() bool {
	if p.peek() == '#' {
		return true
	}
	if p.peek() == '-' && p.peekAt(1) == '-' {
		next := p.peekAt(2)
		return next == 0 || isSpaceRune(next) || unicode.IsControl(next)
	}
	return false
}

// skipWhitespaceAndComments consumes whitespace and comments. Returns an
// error (positioned at the starting point) if a block comment is unterminated.
// Also returns whether anything was consumed.
func (p *sqlParser) skipWhitespaceAndComments() (bool, error) {
	start := p.curPos()
	consumed := false
	for !p.eof() {
		r := p.peek()
		if isSpaceRune(r) {
			p.advance()
			consumed = true
			continue
		}
		if p.atLineComment() {
			for !p.eof() && p.peek() != '\n' {
				p.advance()
			}
			consumed = true
			continue
		}
		if r == '/' && p.peekAt(1) == '*' {
			p.advance()
			p.advance()
			closed := false
			for !p.eof() {
				if p.peek() == '*' && p.peekAt(1) == '/' {
					p.advance()
					p.advance()
					closed = true
					break
				}
				p.advance()
			}
			if !closed {
				return true, fmt.Errorf("Comment starting with /* is never closed at %s", start.String())
			}
			consumed = true
			continue
		}
		break
	}
	return consumed, nil
}

// readQuoted consumes a quoted string/identifier beginning at the current pos
func (p *sqlParser) readQuoted() (string, error) {
	start := p.curPos()
	quote := p.advance()
	var sb strings.Builder
	for !p.eof() {
		r := p.advance()
		if r == '\\' && quote != '`' {
			if p.eof() {
				break
			}
			sb.WriteRune(p.advance())
			continue
		}
		if r == quote {
			if p.peek() == quote {
				p.advance()
				sb.WriteRune(quote)
				continue
			}
			return sb.String(), nil
		}
		sb.WriteRune(r)
	}
	if quote == '`' {
		return "", fmt.Errorf("Identifier is missing closing quote at %s", start.String())
	}
	return "", fmt.Errorf("String is missing closing quote at %s", start.String())
}

// readWord consumes an identifier/keyword
func (p *sqlParser) readWord() string {
	var sb strings.Builder
	for !p.eof() && isWordRune(p.peek()) {
		sb.WriteRune(p.advance())
	}
	return sb.String()
}

func (p *sqlParser) atDelimiter() bool {
	return p.hasPrefix(p.delimiter)
}

func (p *sqlParser) consumeDelimiter() {
	for range []rune(p.delimiter) {
		p.advance()
	}
}

// consumeTrailingWhitespace consumes horizontal whitespace and a single newline
func (p *sqlParser) consumeTrailingWhitespace() {
	for !p.eof() && (p.peek() == ' ' || p.peek() == '\t' || p.peek() == '\r') {
		p.advance()
	}
	if !p.eof() && p.peek() == '\n' {
		p.advance()
	}
}

func (p *sqlParser) textSince(startPos int) string {
	return string(p.runes[startPos:p.pos])
}

// token represents a scanned token within a statement
type token struct {
	kind  rune // 'w' word, 'q' quoted, 'p' punctuation, 'd' delimiter
	val   string
	quote rune
}

// nextStatement parses one statement (possibly a noop of whitespace/comments)
func (p *sqlParser) nextStatement() error {
	startIdx := p.pos
	startPos := p.curPos()
	consumed, err := p.skipWhitespaceAndComments()
	if err != nil {
		return err
	}
	if consumed {
		// emit a noop statement for leading whitespace/comments
		if p.eof() || true {
			p.stmts = append(p.stmts, &Statement{
				File:      p.file,
				LineNo:    startPos.line,
				CharNo:    startPos.col,
				Text:      p.textSince(startIdx),
				Type:      StatementTypeNoop,
				Delimiter: p.delimiter,
			})
		}
		if p.eof() {
			return nil
		}
		startIdx = p.pos
		startPos = p.curPos()
	}
	stmt := &Statement{
		File:      p.file,
		LineNo:    startPos.line,
		CharNo:    startPos.col,
		Delimiter: p.delimiter,
		Type:      StatementTypeUnknown,
	}

	// DELIMITER command: consumes to end of line
	if p.hasPrefixFold("delimiter") && !isWordRune(p.peekAt(9)) {
		for i := 0; i < 9; i++ {
			p.advance()
		}
		for !p.eof() && (p.peek() == ' ' || p.peek() == '\t') {
			p.advance()
		}
		var sb strings.Builder
		for !p.eof() && p.peek() != '\n' && p.peek() != '\r' && p.peek() != ' ' && p.peek() != '\t' {
			sb.WriteRune(p.advance())
		}
		for !p.eof() && p.peek() != '\n' {
			p.advance()
		}
		if !p.eof() {
			p.advance()
		}
		newDelim := sb.String()
		stmt.Type = StatementTypeCommand
		stmt.ObjectType = "delimiter"
		stmt.Text = p.textSince(startIdx)
		if newDelim != "" {
			p.delimiter = newDelim
		}
		p.stmts = append(p.stmts, stmt)
		return nil
	}

	// Scan tokens until delimiter
	var tokens []token
	swallowToEOF := false
	for !p.eof() {
		if p.atDelimiter() {
			p.consumeDelimiter()
			p.consumeTrailingWhitespace()
			break
		}
		r := p.peek()
		if r == '\'' || r == '"' || r == '`' {
			val, err := p.readQuoted()
			if err != nil {
				return err
			}
			tokens = append(tokens, token{kind: 'q', val: val, quote: r})
		} else if isWordRune(r) {
			w := p.readWord()
			tokens = append(tokens, token{kind: 'w', val: w})
			// compound routine body detection with default delimiter
			if !swallowToEOF && p.delimiter == ";" && strings.EqualFold(w, "begin") && isRoutineCreate(tokens) {
				swallowToEOF = true
				for !p.eof() {
					p.advance()
				}
				break
			}
		} else {
			tokens = append(tokens, token{kind: 'p', val: string(r)})
			p.advance()
		}
		_, err := p.skipWhitespaceAndComments()
		if err != nil {
			return err
		}
	}
	stmt.Text = p.textSince(startIdx)
	classifyStatement(stmt, tokens)
	p.stmts = append(p.stmts, stmt)
	return nil
}

// isRoutineCreate checks whether the token list so far represents a
// CREATE PROCEDURE or CREATE FUNCTION statement
func isRoutineCreate(tokens []token) bool {
	if len(tokens) == 0 || tokens[0].kind != 'w' || !strings.EqualFold(tokens[0].val, "create") {
		return false
	}
	for _, t := range tokens[1:] {
		if t.kind == 'w' {
			lv := strings.ToLower(t.val)
			if lv == "procedure" || lv == "function" {
				return true
			}
			if lv == "table" || lv == "view" || lv == "trigger" || lv == "event" || lv == "index" || lv == "database" || lv == "schema" {
				return false
			}
		}
		if t.kind == 'p' && t.val == "(" {
			return false
		}
	}
	return false
}

// classifyStatement determines the statement type and object name
func classifyStatement(stmt *Statement, tokens []token) {
	if len(tokens) == 0 {
		stmt.Type = StatementTypeNoop
		return
	}
	first := tokens[0]
	if first.kind != 'w' {
		return
	}
	switch strings.ToLower(first.val) {
	case "use":
		stmt.Type = StatementTypeCommand
		stmt.ObjectType = "use"
		if len(tokens) > 1 && (tokens[1].kind == 'w' || tokens[1].kind == 'q') {
			stmt.ObjectName = tokens[1].val
		}
		return
	case "create":
		classifyCreate(stmt, tokens)
	}
}

func classifyCreate(stmt *Statement, tokens []token) {
	// find the object type keyword
	idx := -1
	var objType string
	for i := 1; i < len(tokens); i++ {
		t := tokens[i]
		if t.kind != 'w' {
			continue
		}
		lv := strings.ToLower(t.val)
		switch lv {
		case "table", "procedure", "function", "view", "trigger", "event":
			idx = i
			objType = lv
		case "temporary":
			// temporary tables are not tracked
			stmt.Type = StatementTypeUnknown
			return
		case "or", "replace", "definer", "algorithm", "sql", "security", "definer_user",
			"undefined", "merge", "temptable", "invoker", "aggregate", "if", "not", "exists":
			continue
		default:
			// part of definer clause, e.g. root, localhost, etc; keep scanning
			continue
		}
		if idx >= 0 {
			break
		}
	}
	if idx < 0 {
		return
	}
	// Name follows, optionally after IF NOT EXISTS
	i := idx + 1
	for i < len(tokens) && tokens[i].kind == 'w' {
		lv := strings.ToLower(tokens[i].val)
		if lv == "if" || lv == "not" || lv == "exists" {
			i++
			continue
		}
		break
	}
	if i >= len(tokens) {
		return
	}
	nameTok := tokens[i]
	if nameTok.kind == 'p' {
		return
	}
	name := nameTok.val
	qualifier := ""
	// check for schema qualifier
	if i+2 < len(tokens) && tokens[i+1].kind == 'p' && tokens[i+1].val == "." && tokens[i+2].kind != 'p' {
		qualifier = name
		name = tokens[i+2].val
	}
	switch objType {
	case "table", "procedure", "function":
		stmt.Type = StatementTypeCreate
	default:
		stmt.Type = StatementTypeCreateUnsupported
	}
	stmt.ObjectType = objType
	stmt.ObjectName = name
	stmt.ObjectQualifier = qualifier
}

// EscapeIdentifier wraps an identifier in backticks, doubling embedded backticks
func EscapeIdentifier(name string) string {
	return "`" + strings.ReplaceAll(name, "`", "``") + "`"
}
