package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// LogicalSchema represents the set of CREATE statements in a dir for one schema name
type LogicalSchema struct {
	Name    string
	Creates map[string]*Statement
	order   []string
}

func newLogicalSchema(name string) *LogicalSchema {
	return &LogicalSchema{Name: name, Creates: make(map[string]*Statement)}
}

func (ls *LogicalSchema) AddStatement(stmt *Statement) error {
	key := stmt.ObjectKey()
	if existing, ok := ls.Creates[key]; ok {
		return fmt.Errorf("%s %s defined multiple times in same directory: %s line %d and %s line %d",
			stmt.ObjectType, EscapeIdentifier(stmt.ObjectName), existing.File, existing.LineNo, stmt.File, stmt.LineNo)
	}
	ls.Creates[key] = stmt
	ls.order = append(ls.order, key)
	return nil
}

func (ls *LogicalSchema) Len() int {
	return len(ls.Creates)
}

// Dir is a parsed directory
type Dir struct {
	Path               string
	Config             *Config
	OptionFile         *OptionFile
	LogicalSchemas     []*LogicalSchema
	SQLFiles           []string
	UnparsedStatements []*Statement
	ParseError         error
	repoBase           string
	env                string
}

func (dir *Dir) String() string {
	return dir.Path
}

func (dir *Dir) BaseName() string {
	return filepath.Base(dir.Path)
}

// RelPath returns the path relative to the parent of the root dir of this run
func (dir *Dir) RelPath() string {
	rel, err := filepath.Rel(dir.repoBase, dir.Path)
	if err != nil || strings.HasPrefix(rel, "..") {
		return dir.BaseName()
	}
	return rel
}

// ParseDir parses a directory, including ancestor .skeema files, its own
// .skeema file, and all *.sql files directly within it.
func ParseDir(dirPath string, globalConfig *Config) (*Dir, error) {
	cleaned, err := filepath.Abs(filepath.Clean(dirPath))
	if err != nil {
		return nil, err
	}
	dir := &Dir{
		Path:     cleaned,
		Config:   globalConfig.Clone(),
		repoBase: filepath.Dir(cleaned),
		env:      environmentName(globalConfig),
	}
	fi, err := os.Stat(dir.Path)
	if err != nil {
		return nil, err
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("%s is not a directory", dir.Path)
	}

	// Parse ancestor option files, from root down
	if err := dir.parseAncestorOptionFiles(); err != nil {
		return nil, err
	}
	if err := dir.parseContents(); err != nil {
		return nil, err
	}
	// Generator check for root dir uses full config
	if err := dir.checkGenerator(dir.Config.Get("generator")); err != nil {
		return nil, err
	}
	return dir, nil
}

func (dir *Dir) parseAncestorOptionFiles() error {
	// collect ancestors from root to parent
	ancestors := []string{}
	p := filepath.Dir(dir.Path)
	for {
		ancestors = append([]string{p}, ancestors...)
		parent := filepath.Dir(p)
		if parent == p {
			break
		}
		p = parent
	}
	for _, a := range ancestors {
		f, err := loadOptionFile(a, dir.env)
		if err != nil {
			return err
		}
		if f != nil {
			dir.Config.AddSource(f)
		}
	}
	return nil
}

// loadOptionFile loads the .skeema file in dirPath if it exists. Returns nil
// if no file exists there.
func loadOptionFile(dirPath, env string) (*OptionFile, error) {
	path := filepath.Join(dirPath, ".skeema")
	fi, err := os.Lstat(path)
	if err != nil {
		return nil, nil
	}
	if fi.Mode()&os.ModeSymlink != 0 {
		fi, err = os.Stat(path)
		if err != nil {
			return nil, nil
		}
	}
	if !fi.Mode().IsRegular() {
		return nil, NewExitValue(CodeFatalError, "%s is not a regular file, nor a symlink to a regular file", path)
	}
	f := NewOptionFile(dirPath, ".skeema")
	if err := f.Read(knownOptions()); err != nil {
		return nil, err
	}
	f.UseSection(env)
	warnDeprecatedFile(f)
	return f, nil
}

// parseContents parses the dir's own option file and *.sql files
func (dir *Dir) parseContents() error {
	f, err := loadOptionFile(dir.Path, dir.env)
	if err != nil {
		return err
	}
	if f != nil {
		dir.OptionFile = f
		dir.Config.AddSource(f)
	}

	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		return err
	}
	names := []string{}
	for _, e := range entries {
		name := e.Name()
		if !strings.HasSuffix(name, ".sql") {
			continue
		}
		full := filepath.Join(dir.Path, name)
		fi, err := os.Stat(full)
		if err != nil || !fi.Mode().IsRegular() {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	logicalSchemas := map[string]*LogicalSchema{}
	lsOrder := []string{}
	for _, name := range names {
		full := filepath.Join(dir.Path, name)
		dir.SQLFiles = append(dir.SQLFiles, full)
		stmts, err := ParseStatementsInFile(full)
		if err != nil {
			return NewExitValue(CodeFatalError, "File %s: %s", full, err.Error())
		}
