package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strings"
)

var shellSafeRegex = regexp.MustCompile(`^[A-Za-z0-9_.:/@=,+%-]+$`)

// shellQuote quotes a value for safe use in a shell command, if needed
func shellQuote(value string) string {
	if value == "" {
		return "''"
	}
	if shellSafeRegex.MatchString(value) {
		return value
	}
	return "'" + strings.ReplaceAll(value, "'", `'"'"'`) + "'"
}

// ShellOut represents a command to run via /bin/sh -c
type ShellOut struct {
	Command string
}

// NewInterpolatedShellOut builds a ShellOut by substituting {VARIABLE}
// placeholders in command with values from variables (keys uppercase).
// Variables ending in X are treated the same as their base name.
func NewInterpolatedShellOut(command string, variables map[string]string) (*ShellOut, error) {
	var sb strings.Builder
	i := 0
	for i < len(command) {
		c := command[i]
		if c != '{' {
			sb.WriteByte(c)
			i++
			continue
		}
		if i+1 < len(command) && command[i+1] == '{' {
			sb.WriteString("{{")
			i += 2
			continue
		}
		end := strings.IndexByte(command[i:], '}')
		if end < 0 {
			return nil, fmt.Errorf("Variable name missing closing brace: %s", command[i:])
		}
		name := strings.ToUpper(command[i+1 : i+end])
		if strings.HasSuffix(name, "X") {
			name = name[:len(name)-1]
		}
		value, ok := variables[name]
		if !ok {
			return nil, fmt.Errorf("Unknown variable %s", name)
		}
		sb.WriteString(shellQuote(value))
		i += end + 1
	}
	return &ShellOut{Command: sb.String()}, nil
}

func (s *ShellOut) String() string {
	return s.Command
}

// Run runs the command, passing through stdout and stderr
func (s *ShellOut) Run() error {
	if strings.TrimSpace(s.Command) == "" {
		return fmt.Errorf("Attempted to shell out to an empty command string")
	}
	cmd := exec.Command("/bin/sh", "-c", s.Command)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// RunCapture runs the command, capturing stdout and passing through stderr
func (s *ShellOut) RunCapture() (string, error) {
	if strings.TrimSpace(s.Command) == "" {
		return "", fmt.Errorf("Attempted to shell out to an empty command string")
	}
	cmd := exec.Command("/bin/sh", "-c", s.Command)
	var out bytes.Buffer
	cmd.Stdin = os.Stdin
	cmd.Stdout = &out
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	return out.String(), err
}

// RunCaptureSplit runs the command and splits output on newlines, commas, and
// (if no newlines/commas) whitespace, returning non-empty trimmed tokens.
func (s *ShellOut) RunCaptureSplit() ([]string, error) {
	raw, err := s.RunCapture()
	if err != nil {
		return nil, err
	}
	raw = strings.TrimSpace(raw)
	var tokens []string
	if strings.ContainsAny(raw, "\n") {
		tokens = strings.Split(raw, "\n")
	} else if strings.ContainsAny(raw, ",") {
		tokens = strings.Split(raw, ",")
	} else {
		tokens = strings.Fields(raw)
	}
	result := make([]string, 0, len(tokens))
	for _, t := range tokens {
		t = strings.TrimSpace(t)
		if t != "" {
			result = append(result, t)
		}
	}
	return result, nil
}
