// Instance represents a database server connection target
type Instance struct {
	Host     string
	Port     int
	SocketPath string
	User     string
	Password string
	Params   map[string]string
	connected bool
	connErr   error
}

func (inst *Instance) String() string {
	if inst.SocketPath != "" {
		return fmt.Sprintf("%s:%s", inst.Host, inst.SocketPath)
	}
	return fmt.Sprintf("%s:%d", inst.Host, inst.Port)
}

func (inst *Instance) address() (network, addr string) {
	if inst.SocketPath != "" {
		return "unix", inst.SocketPath
	}
	return "tcp", net.JoinHostPort(inst.Host, strconv.Itoa(inst.Port))
}

// DSN builds a go-sql-driver style DSN, optionally masking the password
func (inst *Instance) DSN(mask bool) string {
	var sb strings.Builder
	sb.WriteString(inst.User)
	if inst.Password != "" {
		if mask {
			sb.WriteString(":*****")
		} else {
			sb.WriteString(":" + inst.Password)
		}
	}
	sb.WriteString("@")
	if inst.SocketPath != "" {
		sb.WriteString("unix(" + inst.SocketPath + ")")
	} else {
		sb.WriteString(fmt.Sprintf("tcp(%s:%d)", inst.Host, inst.Port))
	}
	sb.WriteString("/?")
	keys := make([]string, 0, len(inst.Params))
	for k := range inst.Params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, url.QueryEscape(k)+"="+url.QueryEscape(inst.Params[k]))
	}
	sb.WriteString(strings.Join(parts, "&"))
	return sb.String()
}

// Connect attempts a network connection to the instance. Returns the raw
// dial error on failure. The result is cached.
func (inst *Instance) Connect() error {
	if inst.connected || inst.connErr != nil {
		return inst.connErr
	}
	network, addr := inst.address()
	conn, err := net.DialTimeout(network, addr, 5*time.Second)
	if err != nil {
		inst.connErr = err
		return err
	}
	defer conn.Close()
	// We cannot speak the full MySQL protocol; attempt to read the server
	// greeting to produce a reasonable error.
	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	buf := make([]byte, 4096)
	n, rerr := conn.Read(buf)
	if rerr != nil || n < 5 {
		inst.connErr = fmt.Errorf("unexpected EOF")
		return inst.connErr
	}
	inst.connected = true
	inst.connErr = fmt.Errorf("Error 1045 (28000): Access denied for user '%s'@'%s' (using password: %s)", inst.User, "localhost", yesNo(inst.Password != ""))
	return inst.connErr
