	"multistatements":          true,
	"parsetime":                true,
	"allowfallbacktoplaintext": true,
	"loc":                      true,
	"serverpubkey":             true,
	"checkconnliveness":        true,
	"foreign_key_checks":       true,
	"default_storage_engine":   true,
	"interpolateparams":        true,
	"compress":                 true,
}

// SplitConnectOptions parses a comma-separated key=value list, honoring single quotes
func SplitConnectOptions(connectOpts string) (map[string]string, []string, error) {
	result := make(map[string]string)
	order := []string{}
	if connectOpts == "" {
		return result, order, nil
	}
	var startToken int
	var name string
	haveName := false
	var inQuote bool
	s := connectOpts + ","
	for pos := 0; pos < len(s); pos++ {
		c := s[pos]
		if inQuote {
			if c == '\\' && pos+1 < len(s) {
				pos++
				continue
			}
			if c == '\'' {
				inQuote = false
			}
			continue
		}
		switch c {
		case '\'':
			inQuote = true
		case '=':
			if !haveName {
				name = connectOpts[startToken:pos]
				haveName = true
				startToken = pos + 1
			} else {
				return nil, nil, fmt.Errorf("Invalid equals-sign character in option value at byte offset %d in connect-options %q", pos, connectOpts)
			}
		case ',':
			if startToken == pos {
				return nil, nil, fmt.Errorf("Invalid comma placement in option value at byte offset %d in connect-options %q", pos, connectOpts)
			}
			if !haveName {
				return nil, nil, fmt.Errorf("Option %s is missing a value at byte offset %d in connect-options %q", connectOpts[startToken:pos], pos, connectOpts)
			}
			if _, exists := result[name]; !exists {
				order = append(order, name)
			}
			result[name] = s[startToken:pos]
			haveName = false
			name = ""
			startToken = pos + 1
		}
	}
	if inQuote {
		return nil, nil, fmt.Errorf("Unterminated quote in connect-options %q", connectOpts)
	}
	return result, order, nil
}

// connectionParams builds the DSN params for a dir's config
func connectionParams(cfg *Config) (map[string]string, error) {
	params := map[string]string{
		"interpolateParams":      "true",
		"foreign_key_checks":     "0",
		"default_storage_engine": "'InnoDB'",
		"timeout":                "5s",
		"readTimeout":            "20s",
		"writeTimeout":           "5s",
	}
	sslMode, err := cfg.GetEnum("ssl-mode", "disabled", "preferred", "required", "")
	if err != nil {
