		value := userOpts[name]
		if bannedConnectOptions[strings.ToLower(name)] {
			return nil, fmt.Errorf("connect-options is not allowed to contain %s", name)
		}
		if strings.ToLower(name) == "tls" {
			logWarn("Setting the tls option in connect-options is deprecated, and will no longer be allowed in Skeema v2. Use the dedicated ssl-mode option instead.")
			delete(params, "allowFallbackToPlaintext")
		}
		params[name] = value
	}
	return params, nil
}

// SplitHostOptionalPort splits "host:port" into host and port; port 0 if absent
func SplitHostOptionalPort(addr string) (host string, port int, err error) {
	if addr == "" {
		return "", 0, fmt.Errorf("Address is empty")
	}
	if addr[0] == '[' {
		end := strings.IndexByte(addr, ']')
		if end < 0 {
			return "", 0, fmt.Errorf("Address %s has unterminated bracket", addr)
		}
		host = addr[1:end]
		rest := addr[end+1:]
		if rest == "" {
			return host, 0, nil
		}
		if rest[0] != ':' {
			return "", 0, fmt.Errorf("Address %s has invalid characters after bracket", addr)
		}
		port, err = strconv.Atoi(rest[1:])
		if err != nil {
			return "", 0, fmt.Errorf("Address %s has invalid port", addr)
		}
		return host, port, nil
	}
	if strings.Count(addr, ":") > 1 {
		// bare IPv6 address without port
		return addr, 0, nil
	}
	if idx := strings.IndexByte(addr, ':'); idx >= 0 {
		host = addr[:idx]
		port, err = strconv.Atoi(addr[idx+1:])
		if err != nil || port < 0 {
			return "", 0, fmt.Errorf("Address %s has invalid port", addr)
		}
		return host, port, nil
	}
	return addr, 0, nil
}

// Hostnames returns the list of hostnames this dir maps to
func (dir *Dir) Hostnames() ([]string, error) {
	if dir.Config.Changed("host-wrapper") {
		variables := map[string]string{
			"HOST":        dir.Config.Get("host"),
			"ENVIRONMENT": dir.env,
			"DIRNAME":     dir.BaseName(),
			"DIRPATH":     dir.Path,
			"SCHEMA":      dir.Config.Get("schema"),
		}
		shellOut, err := NewInterpolatedShellOut(dir.Config.Get("host-wrapper"), variables)
		if err != nil {
			return nil, err
		}
		return shellOut.RunCaptureSplit()
	}
	return dir.Config.GetSlice("host", ',', true), nil
