// Password returns the password for connecting, prompting if the password
// option was supplied without a value in a dir option file.
func (dir *Dir) Password(hosts ...string) (string, error) {
	if dir.Config.Supplied("password") && !dir.Config.SuppliedWithValue("password") {
		if v, ok := dir.Config.runtimeO["password"]; ok {
			return v, nil
		}
		target := fmt.Sprintf("%s@%s", dir.Config.Get("user"), strings.Join(hosts, ","))
		pw, err := promptPassword(fmt.Sprintf("Enter password for %s: ", target))
		if err != nil {
			return "", fmt.Errorf("Unable to prompt password for %s: %s", target, err)
		}
		dir.Config.SetRuntimeOverride("password", pw)
		return pw, nil
	}
	return resolvedPassword(dir.Config), nil
}

// Instances returns the instances this dir maps to (without connecting)
func (dir *Dir) Instances() ([]*Instance, error) {
	hosts, err := dir.Hostnames()
	if err != nil {
		return nil, err
	}
	if len(hosts) == 0 {
		return nil, nil
	}
	params, err := connectionParams(dir.Config)
	if err != nil {
		return nil, fmt.Errorf("Invalid connection options: %s", err)
	}
	password, err := dir.Password(hosts...)
	if err != nil {
		return nil, err
	}
	user := dir.Config.Get("user")
	optPort, portSupplied := dir.Port()
	instances := make([]*Instance, 0, len(hosts))
	for _, host := range hosts {
		h, p, err := SplitHostOptionalPort(host)
		if err != nil {
			return nil, err
		}
		inst := &Instance{Host: h, User: user, Password: password, Params: params}
		if p > 0 {
			if portSupplied && optPort != p {
				return nil, fmt.Errorf("Port was supplied as %d inside hostname %s but as %d in option file", p, host, optPort)
			}
			inst.Port = p
		} else if h == "localhost" && !portSupplied {
			inst.SocketPath = dir.Config.Get("socket")
		} else {
			inst.Port = optPort
		}
		if inst.SocketPath == "" && inst.Port <= 0 {
			rawPort, _ := dir.Config.GetInt("port")
			return nil, fmt.Errorf("Invalid connection information for %s (DSN=%s): invalid port %d supplied", dir, inst.DSN(true), rawPort)
		}
		instances = append(instances, inst)
	}
	return instances, nil
}

// FirstInstance returns the first instance that can be connected to
func (dir *Dir) FirstInstance() (*Instance, error) {
	instances, err := dir.Instances()
	if err != nil {
		return nil, err
	}
	if len(instances) == 0 {
		return nil, nil
	}
	var lastErr error
	for _, inst := range instances {
		if err := inst.Connect(); err == nil {
			return inst, nil
		} else {
			lastErr = err
		}
	}
	if len(instances) == 1 {
		return nil, NewConfigError("Unable to connect to %s for %s: %s", instances[0], dir, lastErr)
	}
	return nil, NewConfigError("Unable to connect to any of %d database servers for %s; last error %s", len(instances), dir, lastErr)
}
