package main

import (
	"fmt"
)

const pushDescription = `Modifies the schemas on database server(s) to match the corresponding filesystem
representation of them. This essentially performs the same diff logic as ` + "`skeema" + `
diff` + "`" + `, but then actually runs the generated DDL. You should generally run
` + "`skeema diff`" + ` first to see what changes will be applied.

You may optionally pass an environment name as a command-line arg. This will
affect which section of .skeema config files is used for processing. For
example, running ` + "`skeema push staging`" + ` will apply config directives from the
[staging] section of config files, as well as any sectionless directives at the
top of the file. If no environment name is supplied, the default is
"production".

An exit code of 0 will be returned if the operation was fully successful; 1 if
at least one table could not be updated due to use of unsupported features, or
if the --dry-run option was used and differences were found; or 2+ if a fatal
error occurred.`

func pushCommand() *Command {
	cmd := NewCommand("push", "Alter objects on DBs to reflect the filesystem representation", pushDescription, PushHandler)
	cmd.AddArg("environment", true)
	addDiffPushOptions(cmd, false)
	return cmd
}

// Target represents a dir + instance + schema combination
type Target struct {
	Dir        *Dir
	Instance   *Instance
	SchemaName string
}

func PushHandler(cfg *Config) error {
	dir, err := ParseDir(".", cfg)
	if err != nil {
		return err
	}
	concurrent, err := cfg.GetInt("concurrent-servers")
	if err != nil {
		return NewExitValue(CodeBadConfig, "%s", err.Error())
	}
	if concurrent < 1 {
		return NewExitValue(CodeBadConfig, "concurrent-instances cannot be less than 1")
	}

	targets, skipCount := TargetsForDir(dir, 5)
	// Without a reachable database server, no targets can be processed. Any
	// targets returned here would have connected successfully; attempt the
	// operation which (lacking protocol support) yields an error.
	for _, t := range targets {
		logErrorf("Skipping %s for %s: %s", t.Instance, t.Dir, t.Instance.connErr)
		skipCount++
	}
	if skipCount > 0 {
		return NewExitValue(CodeFatalError, "Skipped %d operation%s due to problem%s", skipCount, pluralS(skipCount), pluralS(skipCount))
	}
	return nil
}

func pluralS(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// TargetsForDir builds targets for a dir and its subdirs, logging and counting
// any that must be skipped.
func TargetsForDir(dir *Dir, maxDepth int) (targets []*Target, skipCount int) {
	if dir.HasHost() && dir.HasSchema() {
		var instances []*Instance
		var err error
		if dir.Config.GetBool("first-only") {
			var inst *Instance
			inst, err = dir.FirstInstance()
			if inst != nil {
				instances = []*Instance{inst}
			}
		} else {
			instances, err = dir.Instances()
		}
		if err != nil {
			logErrorf("Skipping %s: %s", dir, err)
			skipCount++
		} else if len(instances) == 0 {
			logWarnf("Skipping %s: directory maps to an empty list of database servers", dir)
			if dir.Config.Changed("host-wrapper") {
				logWarn("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
			}
		} else {
			for _, inst := range instances {
				if err := inst.Connect(); err != nil {
					logErrorf("Skipping %s for %s: %s", inst, dir, err)
					skipCount++
					continue
				}
				targets = append(targets, &Target{Dir: dir, Instance: inst, SchemaName: dir.Config.Get("schema")})
			}
		}
	} else if dir.HasSchema() {
		logWarnf("Skipping %s: no host defined for environment %q", dir, dir.env)
		logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", dir.env)
	}

	if maxDepth <= 0 {
		return
	}
	subdirs, err := dir.Subdirs()
	if err != nil {
		logErrorf("Skipping subdirs of %s: %s", dir, err)
		skipCount++
		return
	}
	for _, sub := range subdirs {
		if sub.ParseError != nil {
			logErrorf("Skipping %s: %s", sub, sub.ParseError)
			skipCount++
			continue
		}
		subTargets, subSkip := TargetsForDir(sub, maxDepth-1)
		targets = append(targets, subTargets...)
		skipCount += subSkip
	}
	return
}

func unusedFmt() string { return fmt.Sprint() }
EOF
echo ok"}

