package main

import (
	"fmt"
	"os/exec"
)

// workspaceCheck validates workspace-related options for a dir and attempts to
// obtain a connection to the database server (for workspace=temp-schema) or
// to locate the docker client (for workspace=docker). Returns an error
// describing why the dir must be skipped.
func workspaceCheck(dir *Dir) error {
	cfg := dir.Config
	if _, err := cfg.GetEnum("docker-cleanup", "none", "stop", "destroy"); err != nil {
		return NewConfigError("%s", err.Error())
	}
	if _, err := cfg.GetEnum("temp-schema-binlog", "on", "off", "auto"); err != nil {
		return NewConfigError("%s", err.Error())
	}
	if _, err := cfg.GetEnum("temp-schema-mode", "serial", "light", "regular", "heavy", "extreme"); err != nil {
		return NewConfigError("%s", err.Error())
	}
	if cfg.Supplied("temp-schema-threads") {
		if n, err := cfg.GetInt("temp-schema-threads"); err != nil || n < 1 {
			return NewConfigError("temp-schema-threads cannot be less than 1")
		}
	}
	workspace := cfg.Get("workspace")
	if workspace == "docker" {
		if cfg.Get("flavor") == "" {
			return NewConfigError("This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", dir.env)
		}
		if _, err := exec.LookPath("docker"); err != nil {
			return fmt.Errorf("unable to find `docker` command-line client among directories in PATH\nSkeema v1.11+ no longer includes a built-in Docker client. If you are using workspace=docker while also running `skeema` itself in a container, be sure to put a Linux `docker` client CLI binary in the container as well.\nFor more information, see https://github.com/skeema/skeema/issues/186#issuecomment-1648483625")
		}
		return fmt.Errorf("Unable to use Docker workspace: docker daemon is not available")
	}
	if !dir.HasHost() {
		return NewConfigError("This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", dir.env)
	}
	inst, err := dir.FirstInstance()
	if err != nil {
		return err
	}
	if inst == nil {
		return NewConfigError("This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", dir.env)
	}
	return nil
}

// exitCodeForDirError returns the exit code appropriate for an error
// encountered while processing a dir
func exitCodeForDirError(err error) int {
	if IsConfigError(err) {
		return CodeBadConfig
	}
	if code := ExitCode(err); code != CodeSuccess {
		return code
	}
	return CodeFatalError
}
