pre-installed / system schemas (information_schema, performance_schema, mysql,
sys, test).

You may optionally pass an environment name as a command-line arg. This will
affect which section of .skeema config files the host-related options are
written to. For example, running ` + "`skeema init staging`" + ` will add config
directives to the [staging] section of config files. If no environment name is
supplied, the default is "production", so directives will be written to the
[production] section of the file.`

func initCommand() *Command {
	cmd := NewCommand("init", "Save a DB server's schemas to the filesystem", initDescription, InitHandler)
	cmd.AddArg("environment", true)
	cmd.AddOptions("",
		StringOption("dir", 'd', "<hostname>", "Subdir name to use for this host's schemas"),
		StringOption("host", 'h', "", "Database hostname or IP address"),
		BoolOption("include-auto-inc", 0, false, "Include starting auto-inc values in table files"),
		StringOption("port", 'P', "3306", "Port to use for database host"),
		StringOption("schema", 0, "", "Only import the one specified schema; skip creation of subdirs for each schema"),
		StringOption("socket", 'S', "/tmp/mysql.sock", "Absolute path to Unix socket file used if host is localhost"),
		BoolOption("strip-partitioning", 0, false, "Omit PARTITION BY clause when writing partitioned tables to filesystem"),
		StringOption("temp-schema", 't', "_skeema_tmp", "Name of temporary schema for intermediate operations").Hidden(),
