}

func InitHandler(cfg *Config) error {
	if !cfg.OnCLI("host") {
		return NewExitValue(CodeBadConfig, "Option --host must be supplied on the command-line")
	}
	environment := "production"
	if cfg.HasArg("environment") {
		environment = cfg.Arg("environment")
	}
	if environment == "" {
		return NewExitValue(CodeBadConfig, "Environment name cannot be empty")
	}

