	var dirPath string
	if cfg.Changed("dir") {
		dirPath = cfg.Get("dir")
	} else {
		dirPath = cfg.Get("host")
		if cfg.Supplied("port") && !strings.Contains(dirPath, ":") {
			dirPath += ":" + cfg.Get("port")
		}
	}
	dirPath = strings.TrimRight(dirPath, "/")
	if dirPath == "" {
		dirPath = "."
	}
	fi, err := os.Stat(dirPath)
	if err != nil || !fi.IsDir() {
