const addEnvDescription = `Modifies the .skeema file in an existing host directory to add a new named
environment. For example, if ` + "`skeema init`" + ` was previously used to create a dir
for a host with the default "production" environment, ` + "`skeema add-environment`" + `
could be used to define a "staging" or "development" environment pointing at a
different host and port, or perhaps a "local" environment pointing at localhost
and a socket path.

This command currently only handles very simple cases. For many situations,
editing .skeema files directly is a better approach.`

func addEnvCommand() *Command {
	cmd := NewCommand("add-environment", "Add a new named environment to an existing host directory", addEnvDescription, AddEnvHandler)
	cmd.AddArg("environment", false)
	cmd.AddOptions("",
		StringOption("dir", 'd', ".", "Base dir for this host's schemas"),
		StringOption("host", 'h', "", "Database hostname or IP address"),
		StringOption("port", 'P', "3306", "Port to use for database host"),
		StringOption("socket", 'S', "/tmp/mysql.sock", "Absolute path to Unix socket file used if host is localhost"),
	)
	return cmd
}

// options which get persisted from the CLI into the new environment section
var addEnvPersistedOptions = []string{"user", "connect-options", "ignore-schema", "ignore-table", "ignore-proc", "ignore-func", "ssl-mode"}

func AddEnvHandler(cfg *Config) error {
	dirPath := cfg.Get("dir")
	fi, err := os.Stat(dirPath)
	if err != nil {
		return NewExitValue(CodeBadConfig, "In add-environment, --dir must refer to a directory that already exists")
	}
	if !fi.IsDir() {
		return NewExitValue(CodeBadConfig, "--dir=%s already exists but is not a directory", dirPath)
	}
	dir, err := ParseDir(dirPath, cfg)
	if err != nil {
		return err
	}
	if dir.OptionFile == nil {
		return NewExitValue(CodeBadConfig, "Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", dir)
	}
	environment := cfg.Arg("environment")
	if environment == "" || strings.ContainsAny(environment, "[]") {
		return NewExitValue(CodeBadConfig, "Environment name \"%s\" is invalid", environment)
	}
	if dir.OptionFile.HasSection(environment) {
		return NewExitValue(CodeBadConfig, "Environment name \"%s\" already defined in %s", environment, dir.OptionFile.Path())
	}
	if !cfg.OnCLI("host") {
		return NewExitValue(CodeBadConfig, "`skeema add-environment` requires --host to be supplied on command-line")
	}

	instances, err := dir.Instances()
	if err != nil {
		return NewExitValue(CodeBadConfig, "%s", err.Error())
	}
	if len(instances) == 0 {
		return NewExitValue(CodeBadConfig, "`skeema add-environment` requires --host to be supplied on command-line")
	}
	inst := instances[0]
	f := dir.OptionFile
	f.SetOptionValue(environment, "host", inst.Host)
	if inst.SocketPath != "" {
		f.SetOptionValue(environment, "socket", inst.SocketPath)
	} else {
		f.SetOptionValue(environment, "port", itoa(inst.Port))
	}
	// Flavor detection requires a working connection
	if err := inst.Connect(); err != nil || true {
		logWarnf("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", f.Path())
	}
	for _, name := range addEnvPersistedOptions {
		if cfg.OnCLI(name) {
			f.SetOptionValue(environment, name, cfg.Get(name))
		}
	}
	if err := f.Write(true); err != nil {
		return NewExitValue(CodeCantCreate, "Unable to write to %s: %s", f.Path(), err)
	}
	logInfof("Added environment [%s] to %s", environment, f.Path())
	return nil
}

func itoa(n int) string {
	return strings.TrimSpace(strings.Replace(fmtInt(n), " ", "", -1))
}
