				i += 2
				continue
			}
			return
		case "definer":
			if i+2 >= len(tokens) || tokens[i+1].kind != 'p' || tokens[i+1].val != "=" {
				return
			}
			i += 2
			// user spec: name[@host] or CURRENT_USER[()]
			if tokens[i].kind == 'p' {
				return
			}
			i++
			if i+1 < len(tokens) && tokens[i].kind == 'p' && tokens[i].val == "@" && tokens[i+1].kind != 'p' {
				i += 2
			} else if i+1 < len(tokens) && tokens[i].kind == 'p' && tokens[i].val == "(" && tokens[i+1].kind == 'p' && tokens[i+1].val == ")" {
				i += 2
			}
			continue
		case "algorithm":
			if i+2 < len(tokens) && tokens[i+1].kind == 'p' && tokens[i+1].val == "=" && tokens[i+2].kind == 'w' {
				i += 3
				continue
			}
			return
		case "sql":
			if i+2 < len(tokens) && tokens[i+1].kind == 'w' && strings.EqualFold(tokens[i+1].val, "security") && tokens[i+2].kind == 'w' {
				i += 3
				continue
			}
			return
		case "table", "procedure", "function", "view", "trigger", "event":
			objType = lv
			i++
		default:
			return
		}
	}
	if objType == "" {
		return
	}
	// optional IF NOT EXISTS
	if i+2 < len(tokens) && tokens[i].kind == 'w' && strings.EqualFold(tokens[i].val, "if") &&
		tokens[i+1].kind == 'w' && strings.EqualFold(tokens[i+1].val, "not") &&
		tokens[i+2].kind == 'w' && strings.EqualFold(tokens[i+2].val, "exists") {
		i += 3
	}
	if i >= len(tokens) {
		return
	}
	name, ok := identifierValue(tokens[i])
	if !ok {
		return
	}
	qualifier := ""
	if i+2 < len(tokens) && tokens[i+1].kind == 'p' && tokens[i+1].val == "." {
		second, ok := identifierValue(tokens[i+2])
		if !ok {
			return
		}
		qualifier = name
		name = second
		i += 2
	}
	i++
	switch objType {
	case "table":
		stmt.Type = StatementTypeCreate
		// CREATE TABLE ... SELECT is unsupported but still identifies the table
		depth := 0
		for j := i; j < len(tokens); j++ {
			t := tokens[j]
			if t.kind == 'p' {
				if t.val == "(" {
					depth++
				} else if t.val == ")" {
					depth--
				}
				continue
			}
			if t.kind == 'w' && depth == 0 && (strings.EqualFold(t.val, "select") || strings.EqualFold(t.val, "as")) {
				stmt.Type = StatementTypeCreateUnsupported
				break
			}
		}
	case "procedure", "function":
		stmt.Type = StatementTypeCreate
	default:
		stmt.Type = StatementTypeUnknown
	}
	stmt.ObjectType = objType
	stmt.ObjectName = name
	stmt.ObjectQualifier = qualifier
}

var numericIdentRegex = regexp.MustCompile(`^[0-9]+([eE][0-9]+)?$`)

// identifierValue returns the identifier represented by a token, if valid
func identifierValue(t token) (string, bool) {
	switch t.kind {
	case 'w':
		if numericIdentRegex.MatchString(t.val) {
			return "", false
		}
		return t.val, true
	case 'q':
		if t.quote == '`' && t.val != "" {
			return t.val, true
		}
	}
	return "", false
}

