var numericIdentRegex = regexp.MustCompile(`^[0-9]+([eE][0-9]+)?$`)

// identifierValue returns the identifier represented by a token, if valid
func identifierValue(t token) (string, bool) {
	switch t.kind {
	case 'w':
		if numericIdentRegex.MatchString(t.val) {
			return "", false
		}
		return t.val, true
	case 'q':
		if t.quote == '`' && t.val != "" {
			return t.val, true
		}
	}
	return "", false
}

